<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'
import { invoke } from '@tauri-apps/api/core'
import { Mic, Upload, LoaderCircle, Search, Check, Square } from 'lucide-vue-next'
const emit=defineEmits<{search:[query:string]}>()
const configured=ref(false), configLoaded=ref(false), token=ref(''), tokenBusy=ref(false), busy=ref(false), recording=ref(false), seconds=ref(0), message=ref(''), result=ref<{title:string;artist:string;album?:string}|null>(null), input=ref<HTMLInputElement>()
let recorder:MediaRecorder|undefined, stream:MediaStream|undefined, timer:ReturnType<typeof setInterval>|undefined, alive=true, cancelled=false
onMounted(async()=>{try{configured.value=await invoke<boolean>('recognition_config')}catch{message.value='无法读取识曲配置'}finally{configLoaded.value=true}})
function release(){stream?.getTracks().forEach(t=>t.stop());stream=undefined;if(timer)clearInterval(timer);timer=undefined;recording.value=false}
onUnmounted(()=>{alive=false;cancelled=true;if(recorder?.state==='recording')recorder.stop();release();token.value=''})
async function saveToken(){tokenBusy.value=true;message.value='';try{await invoke('save_recognition_token',{token:token.value});configured.value=!!token.value.trim();token.value='';message.value=configured.value?'Token 已保存到 Windows 凭据管理器':'已清除识曲 Token'}catch(e){message.value=String(e)}finally{tokenBusy.value=false}}
async function wav(blob:Blob){const context=new AudioContext({sampleRate:16000});try{const audio=await context.decodeAudioData(await blob.arrayBuffer());const count=Math.min(audio.length,Math.floor(audio.sampleRate*12));if(count<audio.sampleRate*2)throw Error('片段太短，请至少提供 2 秒音乐');const out=new ArrayBuffer(44+count*2),view=new DataView(out);const text=(at:number,s:string)=>{for(let i=0;i<s.length;i++)view.setUint8(at+i,s.charCodeAt(i))};text(0,'RIFF');view.setUint32(4,36+count*2,true);text(8,'WAVE');text(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,audio.sampleRate,true);view.setUint32(28,audio.sampleRate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);text(36,'data');view.setUint32(40,count*2,true);const channels=Array.from({length:audio.numberOfChannels},(_,i)=>audio.getChannelData(i));for(let i=0;i<count;i++){let sample=0;for(const channel of channels)sample+=channel[i]/channels.length;sample=Math.max(-1,Math.min(1,sample));view.setInt16(44+i*2,sample<0?sample*32768:sample*32767,true)}return Array.from(new Uint8Array(out))}finally{await context.close()}}
async function recognize(blob:Blob){busy.value=true;message.value='正在识别，请稍候…';result.value=null;try{const bytes=await wav(blob);if(!alive||cancelled)return;const data=await invoke<{title:string;artist:string;album?:string}>('recognize_audio',{bytes});if(alive){result.value=data;message.value='找到这首歌了'}}catch(e){if(alive)message.value=String(e)}finally{if(alive)busy.value=false}}
async function file(e:Event){const el=e.target as HTMLInputElement;const f=el.files?.[0];el.value='';if(!f)return;if(f.size>20_000_000){message.value='请选择小于 20 MB 的音频文件，仅上传开头 12 秒';return}cancelled=false;await recognize(f)}
async function record(){if(!configured.value||busy.value)return;message.value='';result.value=null;cancelled=false;busy.value=true;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('当前环境不支持麦克风录音，请改用上传音频片段');stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!alive||cancelled){release();return}const chunks:BlobPart[]=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=()=>{cancelled=true;release();busy.value=false;message.value='录音失败，请检查麦克风或改用上传片段'};recorder.onstop=()=>{const type=recorder?.mimeType||'audio/webm';release();if(alive&&!cancelled)void recognize(new Blob(chunks,{type}));else busy.value=false};recorder.start();seconds.value=0;recording.value=true;message.value='请让麦克风靠近正在播放音乐的声源';timer=setInterval(()=>{seconds.value++;if(seconds.value>=12)recorder?.stop()},1000)}catch(e){release();busy.value=false;if(alive)message.value=e instanceof DOMException&&e.name==='NotAllowedError'?'麦克风权限被拒绝，可在系统设置中授权，或改用上传片段':String(e)}}
function cancel(){cancelled=true;if(recorder?.state==='recording')recorder.stop();release();message.value='已取消录音，音频没有上传'}
</script>
<template>
 <span class="modal-symbol"><Mic :size="25"/></span><h2>这首歌，叫什么？</h2><p class="muted">录下身边的旋律，或上传一段原曲音频。</p>
 <div class="info-box">识曲由 AudD 提供。点击录制或上传后，会将最多 12 秒的音频片段发送到 AudD；录音仅在你点击后开始。需自备 API Token，服务额度及费用由 AudD 决定。暂不支持哼唱识曲。</div>
 <label>AudD API Token <span v-if="configured" class="token-saved"><Check :size="12"/>已配置</span><input v-model="token" class="field" type="password" autocomplete="off" :placeholder="configured?'输入新 Token 可替换，留空点击可清除':'在 dashboard.audd.io 获取 Token'" :disabled="busy"/></label>
 <button class="secondary wide" :disabled="busy||tokenBusy||!configLoaded||(!configured&&!token.trim())" @click="saveToken">{{tokenBusy?'保存中…':token.trim()?'保存 Token':configured?'清除已保存 Token':'请先配置 Token'}}</button>
 <div class="recognize-actions"><button v-if="!recording" class="primary" :disabled="busy||!configured" @click="record"><LoaderCircle v-if="busy" class="spin" :size="17"/><Mic v-else :size="17"/>{{busy?'正在识别…':'录制 12 秒并识别'}}</button><button v-else class="secondary" @click="cancel"><Square :size="16"/>取消录音 · {{seconds}}s</button><button class="secondary" :disabled="busy||!configured" @click="input?.click()"><Upload :size="16"/>上传片段并识别</button></div>
 <p v-if="message" class="recognize-message" role="status">{{message}}</p>
 <div v-if="result" class="recognize-result"><strong>{{result.title}}</strong><p>{{result.artist}}<span v-if="result.album"> · {{result.album}}</span></p><button class="primary wide" @click="emit('search',`${result.title} ${result.artist}`)"><Search :size="16"/>在 B 站查找这首歌</button></div>
 <input ref="input" type="file" hidden accept="audio/*,.mp3,.wav,.m4a,.ogg,.flac,.aac" @change="file"/>
</template>
